import numpy as np

def motor_thrusts(T, tau_x, tau_y, tau_z, a=0.159, gamma=0.016):
    """X-layout quadrotor, motors 1..4 = front-left, front-right, rear-right, rear-left,
    1 and 3 spinning clockwise. Return the four motor thrusts (N), as a NumPy array, that give
    total thrust T (N) and body torques tau_x, tau_y, tau_z (N m)."""
    return np.full(4, T / 4)

exercises.reference:
import numpy as np

def motor_thrusts(T, tau_x, tau_y, tau_z, a=0.159, gamma=0.016):
    s_roll = np.array([1, -1, -1, 1])
    s_pitch = np.array([-1, -1, 1, 1])
    s_yaw = np.array([1, -1, 1, -1])
    return T / 4 + s_roll * tau_x / (4 * a) + s_pitch * tau_y / (4 * a) + s_yaw * tau_z / (4 * gamma)
